//! The on-disk shape of Deepcore's content files.
//!
//! Every struct here maps 1:1 to a RON file under `assets/data/`. They use string ids
//! (`"raw_copper"`) so the files stay human-editable; [`super::registry`] resolves those to
//! compact numeric ids at load time and validates every reference.

use serde::{Deserialize, Serialize};

/// How a block's texture is generated by `tools/atlas_gen` (and the runtime atlas).
#[derive(Clone, Copy, Debug, PartialEq, Serialize, Deserialize)]
pub enum Pattern {
    /// A flat colour.
    Flat,
    /// Fine noise speckle, for stone and dirt.
    Speckle,
    /// Coarse blotches, for gravel and basalt.
    Blotch,
    /// Speckle plus bright flecks of the given colour, for ore blocks.
    OreFleck((f32, f32, f32)),
    /// Horizontal strata, for shale and gneiss.
    Stratified,
    /// A soft inner glow, for uranium and other emissive blocks.
    Glow,
    /// Vertical grain, for wood.
    Grain,
}

/// Which rendering category a block belongs to. Drives meshing and collision.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
pub enum BlockKind {
    /// Ordinary solid cube.
    #[default]
    Solid,
    /// Walk-through (air, water, gas).
    Passable,
    /// A decorative or functional block entity placed as a cube (furnace, chest).
    Machine,
}

/// One block type.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct BlockDef {
    /// Unique string id, e.g. `"granite"`.
    pub id: String,
    /// Human-readable name shown in the UI.
    pub name: String,
    /// Seconds to break with a tier-1 tool at speed 1.0.
    #[serde(default = "default_hardness")]
    pub hardness: f32,
    /// Minimum tool tier required to break it at all.
    #[serde(default)]
    pub min_tier: u8,
    /// Items dropped when broken, as `(item_id, count)`.
    #[serde(default)]
    pub drops: Vec<(String, u32)>,
    /// Base RGB colour, linear 0..1.
    pub color: (f32, f32, f32),
    /// Procedural texture pattern.
    #[serde(default = "default_pattern")]
    pub pattern: Pattern,
    /// Roughness for the PBR material.
    #[serde(default = "default_roughness")]
    pub roughness: f32,
    /// Emissive strength (0 = not emissive).
    #[serde(default)]
    pub emissive: f32,
    /// Radiation emitted when exposed, as `(radius_blocks, dose_per_second)`.
    #[serde(default)]
    pub radiation: Option<(f32, f32)>,
    /// The layer this block is native to, for the depth meter and tooltips.
    #[serde(default)]
    pub layer_hint: Option<u8>,
    /// If set, this block is a machine whose behaviour comes from `machines.ron`.
    #[serde(default)]
    pub machine: Option<String>,
    /// Rendering and collision category.
    #[serde(default)]
    pub kind: BlockKind,
    /// True if the block can be placed by the player from the given item (see items.ron
    /// `places` field). Unbreakable blocks set this to false.
    #[serde(default = "default_true")]
    pub breakable: bool,
}

fn default_hardness() -> f32 {
    1.0
}
fn default_pattern() -> Pattern {
    Pattern::Speckle
}
fn default_roughness() -> f32 {
    0.85
}
fn default_true() -> bool {
    true
}

/// Item category, which decides stacking and behaviour.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub enum ItemCategory {
    /// Raw ore, ingot, plate, chemical: plain stackable material.
    Material,
    /// A block the player can place.
    Block,
    /// A tool with a tier and speed.
    Tool(ToolDef),
    /// A wearable hazard-protection item.
    Wearable(WearableDef),
    /// A machine kit, placed as a block entity.
    MachineKit,
    /// A container such as a canister or fuel cell.
    Container(ContainerDef),
    /// A cosmetic trophy with no crafting use (e.g. the core crystal).
    Trophy,
}

/// Tool parameters.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct ToolDef {
    /// Mining tier; must be >= a block's `min_tier` to break it.
    pub tier: u8,
    /// Speed multiplier in the break-time formula.
    pub speed: f32,
    /// Area mined per action, `(width, height)` across the targeted face.
    #[serde(default = "default_area")]
    pub area: (u8, u8),
    /// Reach in blocks.
    #[serde(default = "default_reach")]
    pub reach: f32,
    /// What powers it.
    #[serde(default)]
    pub energy: ToolEnergy,
}

fn default_area() -> (u8, u8) {
    (1, 1)
}
fn default_reach() -> f32 {
    5.0
}

/// How a tool is powered.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub enum ToolEnergy {
    /// No power needed (hand tools, pickaxe).
    #[default]
    None,
    /// Runs on steam canisters refilled at a boiler.
    Steam { capacity: u32 },
    /// Runs on battery packs charged at a charging station.
    Battery { capacity: u32 },
    /// Runs on a compact core cell with a fixed number of block breaks.
    CoreCell { breaks: u32 },
}

/// Wearable hazard protection.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct WearableDef {
    /// Fraction of radiation dose absorbed, 0..1.
    #[serde(default)]
    pub radiation_resist: f32,
    /// Fraction of heat absorbed, 0..1.
    #[serde(default)]
    pub heat_resist: f32,
    /// True if the wearer can breathe gas.
    #[serde(default)]
    pub gas_proof: bool,
    /// True if the wearer does not need oxygen underwater.
    #[serde(default)]
    pub water_proof: bool,
    /// Extra stamina capacity multiplier.
    #[serde(default = "one")]
    pub stamina_mult: f32,
}

fn one() -> f32 {
    1.0
}

/// A container item's capacity.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct ContainerDef {
    /// Units of the contained resource it holds.
    pub capacity: u32,
    /// What it holds, e.g. `"steam"`, `"battery"`, `"uranium_solution"`.
    pub holds: String,
}

/// One item type.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ItemDef {
    /// Unique string id.
    pub id: String,
    /// Display name.
    pub name: String,
    /// Maximum stack size.
    #[serde(default = "default_stack")]
    pub stack: u32,
    /// Category and behaviour.
    pub category: ItemCategory,
    /// For block items: which block gets placed.
    #[serde(default)]
    pub places: Option<String>,
    /// Icon colour, linear RGB 0..1.
    #[serde(default = "default_icon")]
    pub color: (f32, f32, f32),
    /// Short tooltip description.
    #[serde(default)]
    pub description: String,
}

fn default_stack() -> u32 {
    64
}
fn default_icon() -> (f32, f32, f32) {
    (0.7, 0.7, 0.7)
}

/// The kind of energy a machine consumes.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub enum EnergyKind {
    /// Burns fuel items in a fuel slot.
    Fuel { slots: u8 },
    /// Draws from the steam network.
    Steam { per_second: f32 },
    /// Draws kW from the electric network.
    Electric { kw: f32 },
    /// Runs on shaft power (steam engine drive).
    Shaft { per_second: f32 },
    /// Needs no energy.
    None,
}

/// A machine or station definition.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct MachineDef {
    /// Unique string id.
    pub id: String,
    /// Display name.
    pub name: String,
    /// Footprint in blocks `(x, y, z)`.
    #[serde(default = "unit_size")]
    pub size: (u8, u8, u8),
    /// Energy requirement.
    pub energy: EnergyKind,
    /// Number of input slots.
    #[serde(default = "default_slots")]
    pub input_slots: u8,
    /// Number of output slots.
    #[serde(default = "default_slots")]
    pub output_slots: u8,
    /// Items needed to build it, as `(item_id, count)`.
    #[serde(default)]
    pub build_cost: Vec<(String, u32)>,
    /// Tech node that must be researched before it can be built.
    #[serde(default)]
    pub tech: Option<String>,
    /// True if this machine can be part of a centrifuge cascade.
    #[serde(default)]
    pub cascade: Option<CascadeDef>,
    /// True if this machine is a multi-block reactor shell or part.
    #[serde(default)]
    pub reactor_part: Option<String>,
    /// Short description for the build menu.
    #[serde(default)]
    pub description: String,
}

fn unit_size() -> (u8, u8, u8) {
    (1, 1, 1)
}
fn default_slots() -> u8 {
    2
}

/// Cascade constraints for centrifuges.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct CascadeDef {
    /// Minimum machines in a linked line for the cascade to run.
    pub min: u8,
    /// Maximum machines in a linked line.
    pub max: u8,
}

/// One recipe.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct RecipeDef {
    /// Unique string id.
    pub id: String,
    /// Machine id that runs this recipe, or `"workbench"` / `"hand"` for manual crafting.
    pub machine: String,
    /// Seconds of processing at full speed.
    pub time: f32,
    /// Inputs, as `(item_id, count)`.
    pub inputs: Vec<(String, u32)>,
    /// Outputs, as `(item_id, count)`.
    pub outputs: Vec<(String, u32)>,
    /// Tech node required before the recipe is available.
    #[serde(default)]
    pub tech: Option<String>,
    /// Power draw in kW, used when the machine's energy kind is electric.
    #[serde(default)]
    pub power_kw: Option<f32>,
    /// Fuel items this recipe consumes directly, e.g. coal for a kiln.
    #[serde(default)]
    pub fuel: Vec<(String, u32)>,
}

/// One node of the team tech tree.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct TechNodeDef {
    /// Unique string id.
    pub id: String,
    /// Display name.
    pub name: String,
    /// Era (0..5) this node belongs to.
    pub era: u8,
    /// Parent node ids that must be unlocked first.
    #[serde(default)]
    pub parents: Vec<String>,
    /// Items that must be delivered to the Research Desk.
    #[serde(default)]
    pub cost: Vec<(String, u32)>,
    /// Machine and recipe ids this node unlocks.
    #[serde(default)]
    pub unlocks: Vec<String>,
    /// One-line description for the tree UI.
    #[serde(default)]
    pub description: String,
}

/// An ore's spawn rule inside a layer.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct OreRule {
    /// Block id of the ore block.
    pub block: String,
    /// Chance per chunk to spawn any vein of this ore, 0..1.
    pub frequency: f32,
    /// Vein size range in blocks.
    pub vein_size: (u32, u32),
    /// Restrict the ore to a depth band inside the layer, if set.
    #[serde(default)]
    pub depth_band: Option<(i32, i32)>,
}

/// A hazard's parameters inside a layer.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub enum HazardRule {
    /// Darkness: no ambient light below this depth.
    Darkness,
    /// Water pockets: `Flooding: (pocket_chance: 0.06, max_volume: 512)`.
    Flooding {
        /// Chance per chunk to place a water pocket.
        pocket_chance: f32,
        /// Maximum blocks of water a pocket can release.
        max_volume: u32,
    },
    /// Methane pockets: `Gas: (pocket_chance: 0.05, volume: 40)`.
    Gas {
        /// Chance per chunk to place a gas pocket.
        pocket_chance: f32,
        /// Blocks of methane released when breached.
        volume: u32,
    },
    /// Heat rising with depth: `Heat: (base: 38.0, per_block: 0.02)`.
    Heat {
        /// Temperature at the top of the layer, Celsius.
        base: f32,
        /// Additional degrees per block of depth.
        per_block: f32,
    },
    /// Unsupported spans collapse: `CaveIn: (max_span: 7)`.
    CaveIn {
        /// Widest ceiling span that stays standing.
        max_span: u8,
    },
    /// Ambient radiation from the rock: `Radiation: (dose_per_sec: 0.02)`.
    Radiation {
        /// Dose per second while in the layer.
        dose_per_sec: f32,
    },
}

/// One vertical layer of the mine.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct LayerDef {
    /// Unique string id.
    pub id: String,
    /// Display name.
    pub name: String,
    /// Depth band in blocks below the surface, `(top, bottom)` measured from `y = 511`.
    pub depth: (i32, i32),
    /// The block that fills most of the layer.
    pub base_block: String,
    /// Secondary blocks and their rough share of the layer, 0..1.
    #[serde(default)]
    pub filler_blocks: Vec<(String, f32)>,
    /// Ores found here.
    #[serde(default)]
    pub ores: Vec<OreRule>,
    /// Hazards active here.
    #[serde(default)]
    pub hazards: Vec<HazardRule>,
    /// Ambient temperature in Celsius.
    #[serde(default = "default_temp")]
    pub ambient_temp: f32,
    /// Minimum tool tier needed to dig the base block (mirrors the block's own value).
    #[serde(default)]
    pub min_tier: u8,
    /// Cave density multiplier for this layer.
    #[serde(default = "one")]
    pub cave_density: f32,
}

fn default_temp() -> f32 {
    18.0
}

/// The whole content set, loaded from one directory of RON files.
#[derive(Clone, Debug, Default, Serialize, Deserialize)]
pub struct ContentFiles {
    /// `blocks.ron`
    pub blocks: Vec<BlockDef>,
    /// `items.ron`
    pub items: Vec<ItemDef>,
    /// `recipes.ron`
    pub recipes: Vec<RecipeDef>,
    /// `machines.ron`
    pub machines: Vec<MachineDef>,
    /// `tech_tree.ron`
    pub tech: Vec<TechNodeDef>,
    /// `layers.ron`
    pub layers: Vec<LayerDef>,
    /// `world.ron` (world generation knobs)
    pub world: WorldGenDef,
}

/// Tunable world generation parameters.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct WorldGenDef {
    /// Surface height above bedrock at the camp, in blocks.
    pub surface_y: i32,
    /// How much the surface height varies, in blocks.
    pub surface_amplitude: i32,
    /// Radius of the flat camp area at the centre of the map, in blocks.
    pub camp_radius: i32,
    /// Y coordinate of the bedrock floor.
    pub bedrock_y: i32,
    /// Thickness of the unbreakable bedrock shell.
    pub bedrock_thickness: i32,
    /// Caves: threshold on the 3D noise field, 0..1. Higher means fewer caves.
    pub cave_threshold: f32,
    /// Cave noise scale, in blocks per noise unit.
    pub cave_scale: f32,
    /// Ore noise scale.
    pub ore_scale: f32,
    /// How many trees ring the camp.
    pub tree_count: u32,
    /// Player spawn position in blocks.
    pub spawn: (i32, i32, i32),
}

impl Default for WorldGenDef {
    fn default() -> Self {
        Self {
            surface_y: 480,
            surface_amplitude: 6,
            camp_radius: 28,
            bedrock_y: 0,
            bedrock_thickness: 3,
            cave_threshold: 0.62,
            cave_scale: 34.0,
            ore_scale: 12.0,
            tree_count: 48,
            spawn: (512, 486, 512),
        }
    }
}
